func (knownBotsCodec) buildConfigsPatch(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (wafmodule.Patch, diag.Diagnostics) {
	if configured.IsNull() {
		return knownBotsPatch{}, diagnostics
	}
	if configured.IsUnknown() || planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown known bots configuration", "The configs block must be known during apply.")
		return nil, diagnostics
	}

	var configValues, planValues knownBotsConfigsModel
	diagnostics.Append(configured.As(ctx, &configValues, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planValues, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}

	patch := knownBotsPatch{}
	patch.BadBots, diagnostics = knownBotsConfiguredBool(configValues.BadBots, planValues.BadBots, "bad_bots", diagnostics)
	patch.BadBotsAction, diagnostics = knownBotsConfiguredString(configValues.BadBotsAction, planValues.BadBotsAction, "bad_bots_action", diagnostics)
	if patch.BadBotsAction.Set && !knownBotsConfigBadBotsActionValid(patch.BadBotsAction.Value) {
		diagnostics.AddError("Invalid known bots bad_bots_action", "bad_bots_action must be one of alert, alert_deny, block_period, deny_no_log.")
	}
	patch.GoodBotsAction, diagnostics = knownBotsConfiguredString(configValues.GoodBotsAction, planValues.GoodBotsAction, "good_bots_action", diagnostics)
	if patch.GoodBotsAction.Set && !knownBotsConfigGoodBotsActionValid(patch.GoodBotsAction.Value) {
		diagnostics.AddError("Invalid known bots good_bots_action", "good_bots_action must be one of alert, alert_deny, block_period, bypass, deny_no_log.")
	}
	patch.Status, diagnostics = knownBotsConfiguredBool(configValues.Status, planValues.Status, "status", diagnostics)

	patch.BadBotsList, diagnostics = knownBotsBuildConfiguredBadBotsList(ctx, configValues.BadBotsList, planValues.BadBotsList, diagnostics)

	patch.ExceptionList, diagnostics = knownBotsBuildConfiguredExceptionList(ctx, configValues.ExceptionList, planValues.ExceptionList, diagnostics)

	patch.GoodBotsList, diagnostics = knownBotsBuildConfiguredGoodBotsList(ctx, configValues.GoodBotsList, planValues.GoodBotsList, diagnostics)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return patch, diagnostics
}

func (knownBotsCodec) ValidateResult(ctx context.Context, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) diag.Diagnostics {
	_, diagnostics := knownBotsDecodeScalars(result)
	owned, ownershipDiagnostics := knownBotsOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return diagnostics
	}

	if owned.BadBotsList {
		_, itemDiagnostics := knownBotsDecodeBadBotsList(result.Configs["bad_bots_list"])
		diagnostics.Append(itemDiagnostics...)
	}

	if owned.ExceptionList {
		_, itemDiagnostics := knownBotsDecodeExceptionList(result.Configs["exception_list"])
		diagnostics.Append(itemDiagnostics...)
	}

	if owned.GoodBotsList {
		_, itemDiagnostics := knownBotsDecodeGoodBotsList(result.Configs["good_bots_list"])
		diagnostics.Append(itemDiagnostics...)
	}
	return diagnostics
}

func (knownBotsCodec) Flatten(ctx context.Context, epID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	model := knownBotsResourceModel{
		EPID:     types.StringValue(epID),
		Template: types.BoolValue(result.Template),
		Configs:  types.ObjectNull(knownBotsConfigAttributeTypes),
	}
	scalars, diagnostics := knownBotsDecodeScalars(result)
	if diagnostics.HasError() || result.Template {
		return &model, diagnostics
	}
	owned, ownershipDiagnostics := knownBotsOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	scalarValues := map[string]attr.Value{}
	bad_botsScalar := types.BoolNull()
	if scalars.BadBots != nil {
		bad_botsScalar = types.BoolValue(*scalars.BadBots)
	}
	scalarValues["bad_bots"] = bad_botsScalar
	scalarValues["bad_bots_action"] = types.StringValue(scalars.BadBotsAction)
	scalarValues["good_bots_action"] = types.StringValue(scalars.GoodBotsAction)
	scalarValues["status"] = types.BoolValue(scalars.Status)

	badBotsListList := types.ObjectNull(knownBotsBadBotsListWrapperAttributeTypes)
	if owned.BadBotsList {
		items, itemDiagnostics := knownBotsDecodeBadBotsList(result.Configs["bad_bots_list"])
		diagnostics.Append(itemDiagnostics...)
		subItemOwnedMasks := make(map[string][]bool)
		subItemOwnedMasks["AllowList"] = make([]bool, len(items.Items))
		if ownership.Source == wafmodule.OwnershipConfigured || ownership.Source == wafmodule.OwnershipPriorState {
			ownershipConfigsValue, ownershipConfigsDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
			diagnostics.Append(ownershipConfigsDiagnostics...)
			if !ownershipConfigsValue.IsNull() && !ownershipConfigsValue.IsUnknown() {
				var ownershipConfigs knownBotsConfigsModel
				diagnostics.Append(ownershipConfigsValue.As(ctx, &ownershipConfigs, basetypes.ObjectAsOptions{})...)
				if !ownershipConfigs.BadBotsList.IsNull() && !ownershipConfigs.BadBotsList.IsUnknown() {
					var ownershipWrapper knownBotsWrapperModel
					diagnostics.Append(ownershipConfigs.BadBotsList.As(ctx, &ownershipWrapper, basetypes.ObjectAsOptions{})...)
					if !ownershipWrapper.Items.IsNull() && !ownershipWrapper.Items.IsUnknown() {
						var ownershipItems []knownBotsBadBotsListItemModel
						diagnostics.Append(ownershipWrapper.Items.ElementsAs(ctx, &ownershipItems, false)...)
						for i, ci := range ownershipItems {
							if i < len(subItemOwnedMasks["AllowList"]) && !ci.AllowList.IsNull() {
								subItemOwnedMasks["AllowList"][i] = true
							}
						}
					}
				}
			}
		} else {
			for i := range subItemOwnedMasks["AllowList"] {
				subItemOwnedMasks["AllowList"][i] = true
			}
		}
		// Decode nested sub-item arrays for owned items only (fail-closed on
		// unknown keys). Unowned items leave the nested array nil (opaque).
		// Decode item-level scalar-string-arrays for owned items only (fail-
		// closed on unknown keys). Unowned items leave the array nil (opaque).
		badBotsListRawISA := result.Configs["bad_bots_list"]
		if len(badBotsListRawISA) > 0 && !knownBotsJSONNull(badBotsListRawISA) {
			var badBotsListRawItemsISA []json.RawMessage
			if err := json.Unmarshal(badBotsListRawISA, &badBotsListRawItemsISA); err == nil {
				for riIndex, ri := range badBotsListRawItemsISA {
					var itemObj map[string]json.RawMessage
					if err := json.Unmarshal(ri, &itemObj); err != nil {
						continue
					}
					// Unindexed collection: match the raw parent item to the
					// decoded item by position (decoded items keep wire order).
					j := riIndex
					if j < len(items.Items) {

						if j < len(subItemOwnedMasks["AllowList"]) && subItemOwnedMasks["AllowList"][j] {
							allow_listDecoded := knownBotsBadBotsListDecodeItemStringArrayAllowList(itemObj["allow_list"], fmt.Sprintf("bad_bots_list item %d allow_list", j+1), &diagnostics)
							if allow_listDecoded != nil {
								items.Items[j].AllowList, _ = json.Marshal(allow_listDecoded)
							}
						}
					}
				}
			}
		}
		badBotsListList, itemDiagnostics = knownBotsBadBotsListWrapperValue(items, subItemOwnedMasks)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["bad_bots_list"] = badBotsListList

	exceptionListList := types.ObjectNull(knownBotsExceptionListWrapperAttributeTypes)
	if owned.ExceptionList {
		items, itemDiagnostics := knownBotsDecodeExceptionList(result.Configs["exception_list"])
		diagnostics.Append(itemDiagnostics...)
		subItemOwnedMasks := make(map[string][]bool)
		// Decode nested sub-item arrays for owned items only (fail-closed on
		// unknown keys). Unowned items leave the nested array nil (opaque).
		// Decode item-level scalar-string-arrays for owned items only (fail-
		// closed on unknown keys). Unowned items leave the array nil (opaque).
		exceptionListList, itemDiagnostics = knownBotsExceptionListWrapperValue(items, subItemOwnedMasks)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["exception_list"] = exceptionListList

	goodBotsListList := types.ObjectNull(knownBotsGoodBotsListWrapperAttributeTypes)
	if owned.GoodBotsList {
		items, itemDiagnostics := knownBotsDecodeGoodBotsList(result.Configs["good_bots_list"])
		diagnostics.Append(itemDiagnostics...)
		subItemOwnedMasks := make(map[string][]bool)
		subItemOwnedMasks["DenyList"] = make([]bool, len(items.Items))
		if ownership.Source == wafmodule.OwnershipConfigured || ownership.Source == wafmodule.OwnershipPriorState {
			ownershipConfigsValue, ownershipConfigsDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
			diagnostics.Append(ownershipConfigsDiagnostics...)
			if !ownershipConfigsValue.IsNull() && !ownershipConfigsValue.IsUnknown() {
				var ownershipConfigs knownBotsConfigsModel
				diagnostics.Append(ownershipConfigsValue.As(ctx, &ownershipConfigs, basetypes.ObjectAsOptions{})...)
				if !ownershipConfigs.GoodBotsList.IsNull() && !ownershipConfigs.GoodBotsList.IsUnknown() {
					var ownershipWrapper knownBotsWrapperModel
					diagnostics.Append(ownershipConfigs.GoodBotsList.As(ctx, &ownershipWrapper, basetypes.ObjectAsOptions{})...)
					if !ownershipWrapper.Items.IsNull() && !ownershipWrapper.Items.IsUnknown() {
						var ownershipItems []knownBotsGoodBotsListItemModel
						diagnostics.Append(ownershipWrapper.Items.ElementsAs(ctx, &ownershipItems, false)...)
						for i, ci := range ownershipItems {
							if i < len(subItemOwnedMasks["DenyList"]) && !ci.DenyList.IsNull() {
								subItemOwnedMasks["DenyList"][i] = true
							}
						}
					}
				}
			}
		} else {
			for i := range subItemOwnedMasks["DenyList"] {
				subItemOwnedMasks["DenyList"][i] = true
			}
		}
		// Decode nested sub-item arrays for owned items only (fail-closed on
		// unknown keys). Unowned items leave the nested array nil (opaque).
		// Decode item-level scalar-string-arrays for owned items only (fail-
		// closed on unknown keys). Unowned items leave the array nil (opaque).
		goodBotsListRawISA := result.Configs["good_bots_list"]
		if len(goodBotsListRawISA) > 0 && !knownBotsJSONNull(goodBotsListRawISA) {
			var goodBotsListRawItemsISA []json.RawMessage
			if err := json.Unmarshal(goodBotsListRawISA, &goodBotsListRawItemsISA); err == nil {
				for riIndex, ri := range goodBotsListRawItemsISA {
					var itemObj map[string]json.RawMessage
					if err := json.Unmarshal(ri, &itemObj); err != nil {
						continue
					}
					// Unindexed collection: match the raw parent item to the
					// decoded item by position (decoded items keep wire order).
					j := riIndex
					if j < len(items.Items) {

						if j < len(subItemOwnedMasks["DenyList"]) && subItemOwnedMasks["DenyList"][j] {
							deny_listDecoded := knownBotsGoodBotsListDecodeItemStringArrayDenyList(itemObj["deny_list"], fmt.Sprintf("good_bots_list item %d deny_list", j+1), &diagnostics)
							if deny_listDecoded != nil {
								items.Items[j].DenyList, _ = json.Marshal(deny_listDecoded)
							}
						}
					}
				}
			}
		}
		goodBotsListList, itemDiagnostics = knownBotsGoodBotsListWrapperValue(items, subItemOwnedMasks)
		diagnostics.Append(itemDiagnostics...)
	}
	scalarValues["good_bots_list"] = goodBotsListList
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	model.Configs, diagnostics = types.ObjectValue(knownBotsConfigAttributeTypes, scalarValues)
	return &model, diagnostics
}

func (codec knownBotsCodec) FlattenTemplate(ctx context.Context, templateID string, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) (any, diag.Diagnostics) {
	result.Template = false
	appModelAny, diagnostics := codec.Flatten(ctx, templateID, result, ownership)
	if diagnostics.HasError() || appModelAny == nil {
		return nil, diagnostics
	}
	appModel, ok := appModelAny.(*knownBotsResourceModel)
	if !ok {
		diagnostics.AddError("Unable to flatten known bots template configuration", fmt.Sprintf("Unexpected app model type %T.", appModelAny))
		return nil, diagnostics
	}
	return &wafmodule.TemplateModel{
		TemplateID: types.StringValue(templateID),
		Configs:    appModel.Configs,
	}, diagnostics
}

func (patch knownBotsPatch) Apply(_ context.Context, result *client.WAFModuleResult) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if result == nil {
		diagnostics.AddError("Unable to merge known bots configuration", "The current API result was nil.")
		return diagnostics
	}
	set := func(name string, value any) {
		if err := result.SetConfig(name, value); err != nil {
			diagnostics.AddError("Unable to merge known bots configuration", fmt.Sprintf("Unable to encode %s: %v", name, err))
		}
	}
	if patch.BadBots.Set {
		set("bad_bots", patch.BadBots.Value)
	}
	if patch.BadBotsAction.Set {
		set("bad_bots_action", patch.BadBotsAction.Value)
	}
	if patch.GoodBotsAction.Set {
		set("good_bots_action", patch.GoodBotsAction.Value)
	}
	if patch.Status.Set {
		set("status", patch.Status.Value)
	}

	if patch.BadBotsList.Set {
		// Merge preserved nested sub-item arrays / item string-arrays from the
		// fresh GET into a per-attempt clone of the patch items. This ensures
		// opaque preservation (the PUT carries the fresh GET's nested raw
		// value, including unknown keys and null) and is safe across 409
		// retries (the original patch is not mutated; the clone is rebuilt
		// from each fresh GET).
		badBotsListGetRaw := result.Configs["bad_bots_list"]
		badBotsListPatchItems := make([]knownBotsBadBotsListWireItem, len(patch.BadBotsList.Items))
		copy(badBotsListPatchItems, patch.BadBotsList.Items)
		if len(badBotsListGetRaw) > 0 && !knownBotsJSONNull(badBotsListGetRaw) {
			var badBotsListGetItems []map[string]json.RawMessage
			if err := json.Unmarshal(badBotsListGetRaw, &badBotsListGetItems); err == nil {
				// Preserve omitted nested arrays by matching each patch item to a
				// unique unconsumed fresh-GET item by its "unchanged projection"
				// (canonical content of every known parent field except the
				// wire-only idx and the nested ownership fields). There is no
				// proven stable identity field (idx is regenerated sequentially;
				// cat/name are not unique), so preservation matches by unchanged
				// content, not identity. A unique unconsumed match is required:
				// a changed, new, reordered-differently, or duplicate item with
				// an omitted nested wrapper cannot be matched safely, so the
				// apply is refused (omission means preserve; an ambiguous mapping
				// must fail rather than be guessed). One remote item cannot
				// satisfy two patch items (consumed map).
				badBotsListConsumed := make(map[int]bool, len(badBotsListGetItems))
				for i := range badBotsListPatchItems {
					// Determine whether any nested ownership field is omitted for
					// this patch item; only then is preservation needed.
					badBotsListOmitAny := false
					if len(badBotsListPatchItems[i].AllowList) == 0 {
						badBotsListOmitAny = true
					}
					if badBotsListOmitAny && len(badBotsListGetItems) > 0 {
						// Only preserve when the fresh GET has existing items to
						// preserve from. When the remote collection is empty,
						// every patch item is new: an omitted nested wrapper has
						// nothing to preserve and stays omitted (no refusal).
						match, matchIndex, ok := knownBotsBadBotsListMatchGetItem(badBotsListPatchItems[i], badBotsListGetItems, badBotsListConsumed)
						if !ok {
							diagnostics.AddError("Cannot preserve omitted nested array",
								fmt.Sprintf("configs.bad_bots_list.item[%d] omits a nested ownership wrapper, but the provider could not uniquely match the parent item to the fresh GET by its unchanged content. Apply was refused because omission means preserve. Configure each omitted wrapper explicitly: an empty wrapper sends []; a populated wrapper replaces the array.", i+1))
							return diagnostics
						}
						badBotsListConsumed[matchIndex] = true
						if len(badBotsListPatchItems[i].AllowList) == 0 {
							if subRaw, ok := match["allow_list"]; ok && len(subRaw) > 0 {
								badBotsListPatchItems[i].AllowList = subRaw
							}
						}
					}
				}
			}
		}
		set("bad_bots_list", badBotsListPatchItems)
	}

	if patch.ExceptionList.Set {
		set("exception_list", patch.ExceptionList.Items)
	}

	if patch.GoodBotsList.Set {
		// Merge preserved nested sub-item arrays / item string-arrays from the
		// fresh GET into a per-attempt clone of the patch items. This ensures
		// opaque preservation (the PUT carries the fresh GET's nested raw
		// value, including unknown keys and null) and is safe across 409
		// retries (the original patch is not mutated; the clone is rebuilt
		// from each fresh GET).
		goodBotsListGetRaw := result.Configs["good_bots_list"]
		goodBotsListPatchItems := make([]knownBotsGoodBotsListWireItem, len(patch.GoodBotsList.Items))
		copy(goodBotsListPatchItems, patch.GoodBotsList.Items)
		if len(goodBotsListGetRaw) > 0 && !knownBotsJSONNull(goodBotsListGetRaw) {
			var goodBotsListGetItems []map[string]json.RawMessage
			if err := json.Unmarshal(goodBotsListGetRaw, &goodBotsListGetItems); err == nil {
				// Preserve omitted nested arrays by matching each patch item to a
				// unique unconsumed fresh-GET item by its "unchanged projection"
				// (canonical content of every known parent field except the
				// wire-only idx and the nested ownership fields). There is no
				// proven stable identity field (idx is regenerated sequentially;
				// cat/name are not unique), so preservation matches by unchanged
				// content, not identity. A unique unconsumed match is required:
				// a changed, new, reordered-differently, or duplicate item with
				// an omitted nested wrapper cannot be matched safely, so the
				// apply is refused (omission means preserve; an ambiguous mapping
				// must fail rather than be guessed). One remote item cannot
				// satisfy two patch items (consumed map).
				goodBotsListConsumed := make(map[int]bool, len(goodBotsListGetItems))
				for i := range goodBotsListPatchItems {
					// Determine whether any nested ownership field is omitted for
					// this patch item; only then is preservation needed.
					goodBotsListOmitAny := false
					if len(goodBotsListPatchItems[i].DenyList) == 0 {
						goodBotsListOmitAny = true
					}
					if goodBotsListOmitAny && len(goodBotsListGetItems) > 0 {
						// Only preserve when the fresh GET has existing items to
						// preserve from. When the remote collection is empty,
						// every patch item is new: an omitted nested wrapper has
						// nothing to preserve and stays omitted (no refusal).
						match, matchIndex, ok := knownBotsGoodBotsListMatchGetItem(goodBotsListPatchItems[i], goodBotsListGetItems, goodBotsListConsumed)
						if !ok {
							diagnostics.AddError("Cannot preserve omitted nested array",
								fmt.Sprintf("configs.good_bots_list.item[%d] omits a nested ownership wrapper, but the provider could not uniquely match the parent item to the fresh GET by its unchanged content. Apply was refused because omission means preserve. Configure each omitted wrapper explicitly: an empty wrapper sends []; a populated wrapper replaces the array.", i+1))
							return diagnostics
						}
						goodBotsListConsumed[matchIndex] = true
						if len(goodBotsListPatchItems[i].DenyList) == 0 {
							if subRaw, ok := match["deny_list"]; ok && len(subRaw) > 0 {
								goodBotsListPatchItems[i].DenyList = subRaw
							}
						}
					}
				}
			}
		}
		set("good_bots_list", goodBotsListPatchItems)
	}
	return diagnostics
}

func (knownBotsDefaultTrueModifier) Description(context.Context) string {
	return "Defaults an omitted configured known bots item boolean to true."
}

func (knownBotsDefaultTrueModifier) MarkdownDescription(context.Context) string {
	return "Defaults an omitted configured known bots item boolean with a reviewed true default to `true`."
}

func (knownBotsDefaultTrueModifier) PlanModifyBool(_ context.Context, request planmodifier.BoolRequest, response *planmodifier.BoolResponse) {
	if request.ConfigValue.IsNull() {
		response.PlanValue = types.BoolValue(true)
	}
}

func knownBotsValidateConfiguredBadBotsList(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value knownBotsWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	var items []knownBotsBadBotsListItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("bad_bots_list item %d", index+1)
		if !item.Cat.IsNull() && !item.Cat.IsUnknown() {
			if !knownBotsBadBotsListCatValid(item.Cat.ValueString()) {
				diagnostics.AddError("Invalid known bots item", location+" cat must be one of Crawler, DoS, Scanner, Spam, Trojan.")
			}
		}
	}
	return diagnostics
}

