func knownBotsOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (knownBotsOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return knownBotsOwnershipSet{BadBotsList: false, ExceptionList: false, GoodBotsList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return knownBotsOwnershipSet{BadBotsList: true, ExceptionList: true, GoodBotsList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return knownBotsOwnershipSet{BadBotsList: false, ExceptionList: false, GoodBotsList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown known bots ownership", "The configs ownership state was unknown while flattening.")
		return knownBotsOwnershipSet{BadBotsList: false, ExceptionList: false, GoodBotsList: false}, diagnostics
	}
	var configs knownBotsConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return knownBotsOwnershipSet{BadBotsList: !configs.BadBotsList.IsNull(), ExceptionList: !configs.ExceptionList.IsNull(), GoodBotsList: !configs.GoodBotsList.IsNull()}, diagnostics
}
func knownBotsValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid known bots item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid known bots item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}
